              product={product}
              onViewReviews={(prod) => setSelectedProduct(prod)}
            />
          ))}
        </div>
      )}

      {selectedProduct && (
        <ProductReviewsModal
          product={selectedProduct}
          onClose={() => setSelectedProduct(null)}
        />
      )}
    </section>
  );
}

