  --primary-hover: #1d4ed8;
  --success-color: #16a34a;
  --error-color: #dc2626;
  --background-color: #f8fafc;
  --surface-color: #ffffff;
  --text-primary: #1e293b;
  --text-secondary: #64748b;
  --border-color: #e2e8f0;
  --font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  --border-radius: 8px;
  --transition: all 0.2s ease-in-out;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --max-width: 1200px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--background-color);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

button {
  cursor: pointer;
  font-family: inherit;
  font-size: 1rem;
}

/* Layout */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

main {
  flex: 1;
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1.5rem;
}

/* Header & Navbar */
.header {
  background-color: var(--surface-color);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 10;
}

.navbar {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.nav-brand {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-color);
  cursor: pointer;
}

.nav-controls {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.session-status {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.nav-btn {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 0.5rem 1rem;
  border-radius: var(--border-radius);
  font-weight: 500;
  transition: var(--transition);
}

.nav-btn:hover {
  background-color: var(--background-color);
  border-color: var(--text-secondary);
}

.nav-btn.primary {
  background-color: var(--primary-color);
  border-color: var(--primary-color);
  color: white;
}

.nav-btn.primary:hover {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
}

.cart-badge {
  background-color: var(--primary-color);
  color: white;
  border-radius: 50%;
  padding: 0.2rem 0.6rem;
  font-size: 0.8rem;
  font-weight: 700;
  margin-left: 0.4rem;
}

/* Feedback Notifications */
.feedback-banner {
  padding: 1rem 1.5rem;
  border-radius: var(--border-radius);
  margin-bottom: 1.5rem;
  font-weight: 500;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.feedback-banner.success {
  background-color: #f0fdf4;
  border: 1px solid #bbf7d0;
  color: var(--success-color);
}

.feedback-banner.error {
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  color: var(--error-color);
}

.feedback-close {
  background: none;
  border: none;
  font-size: 1.2rem;
  color: inherit;
  font-weight: 700;
}

/* Catalog View */
.catalog-title {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.catalog-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 640px) {
  .catalog-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .catalog-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.product-card {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
}

.product-image-container {
  height: 200px;
  width: 100%;
  background-color: #f1f5f9;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.product-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Standard Visual Fallback Image Frame if loading fails */
.image-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #e2e8f0;
  color: var(--text-secondary);
  text-align: center;
  padding: 1rem;
}

.image-fallback-icon {
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.availability-tag {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 700;
  color: white;
}

.availability-tag.available {
  background-color: var(--success-color);
}

.availability-tag.out-of-stock {
  background-color: var(--error-color);
}

.product-details {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.product-name {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.product-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
  flex: 1;
}

.product-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
}

.product-price {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-primary);
}

/* Shopping Cart View */
.cart-card {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
}

.cart-empty {
  text-align: center;
  padding: 3rem 1.5rem;
  color: var(--text-secondary);
}

.cart-empty-icon {
  font-size: 3rem;
  margin-bottom: 1rem;
}

.cart-items-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.cart-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  border-bottom: 1px solid var(--border-color);
  flex-wrap: wrap;
  gap: 1rem;
}

.cart-item-info {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex: 1;
  min-width: 200px;
}

.cart-item-image-container {
  width: 60px;
  height: 60px;
  border-radius: 4px;
  overflow: hidden;
  background-color: #f1f5f9;
}

.cart-item-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cart-item-meta h3 {
  font-size: 1rem;
  font-weight: 600;
}

.cart-item-meta p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.cart-item-controls {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.quantity-btn {
  background-color: var(--background-color);
  border: 1px solid var(--border-color);
  width: 28px;
  height: 28px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

.quantity-btn:hover {
  background-color: var(--border-color);
}

.quantity-value {
  font-weight: 600;
  width: 24px;
  text-align: center;
}

.remove-btn {
  background: none;
  border: none;
  color: var(--error-color);
  font-weight: 500;
}

.remove-btn:hover {
  text-decoration: underline;
}

.cart-totals {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 1rem;
  border-top: 2px solid var(--border-color);
  margin-bottom: 1.5rem;
}

.cart-total-label {
  font-size: 1.25rem;
  font-weight: 600;
}

.cart-total-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
}

.cart-actions {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Authentication View (Login/Register) */
.auth-container {
  max-width: 450px;
  margin: 2rem auto;
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}

.auth-tabs {
  display: flex;
  background-color: var(--background-color);
  border-bottom: 1px solid var(--border-color);
}

.auth-tab {
  flex: 1;
  border: none;
  background: none;
  padding: 1rem;
  font-weight: 600;
  color: var(--text-secondary);
  transition: var(--transition);
}

.auth-tab.active {
  background-color: var(--surface-color);
  color: var(--primary-color);
  border-bottom: 2px solid var(--primary-color);
}

.auth-form {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.auth-form-title {
  font-size: 1.5rem;
  font-weight: 700;
  text-align: center;
  margin-bottom: 0.5rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
}

.form-control {
  padding: 0.65rem 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  font-size: 1rem;
  font-family: inherit;
  transition: var(--transition);
}

.form-control:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.auth-error {
  color: var(--error-color);
  font-size: 0.85rem;
  font-weight: 500;
}

.auth-submit-btn {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 0.75rem;
  border-radius: var(--border-radius);
  font-weight: 600;
  transition: var(--transition);
  margin-top: 0.5rem;
}

.auth-submit-btn:hover {
  background-color: var(--primary-hover);
}

/* Simulated Checkout View */
.checkout-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 1024px) {
  .checkout-grid {
    grid-template-columns: 2fr 1fr;
  }
}

.checkout-card {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
}

.checkout-subtitle {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 0.5rem;
}

.fictitious-warning {
  background-color: #fffbeb;
  border: 1px solid #fef3c7;
  color: #b45309;
  padding: 1rem;
  border-radius: var(--border-radius);
  margin-bottom: 1.5rem;
  font-size: 0.9rem;
  font-weight: 500;
  line-height: 1.4;
}

.checkout-summary-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.checkout-summary-item {
  display: flex;
  justify-content: space-between;
  font-size: 0.95rem;
}

.checkout-summary-total {
  display: flex;
  justify-content: space-between;
  font-weight: 700;
  font-size: 1.2rem;
  border-top: 1px solid var(--border-color);
  padding-top: 0.75rem;
}

/* Fictitious Confirmation View */
.confirmation-container {
  max-width: 600px;
  margin: 2rem auto;
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  padding: 2.5rem;
  box-shadow: var(--shadow);
  text-align: center;
}

.success-badge {
  width: 64px;
  height: 64px;
  background-color: #d1fae5;
  color: var(--success-color);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  margin: 0 auto 1.5rem;
}

.confirmation-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--success-color);
  margin-bottom: 0.5rem;
}

.confirmation-msg {
  color: var(--text-secondary);
  font-size: 1rem;
  margin-bottom: 2rem;
}

.confirmation-summary {
  background-color: var(--background-color);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  padding: 1.5rem;
  text-align: left;
  margin-bottom: 2rem;
}

/* Utility Helpers */
.loading-spinner {
  text-align: center;
  padding: 3rem;
  color: var(--text-secondary);
  font-weight: 500;
}

.hidden-label {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* ========================================== */
/*     STAGE 2 PRODUCT REVIEWS & MODERATION  */
/* ========================================== */

/* Reviews Modal Backdrop & Box */
.modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(15, 23, 42, 0.7); /* Deep dark semi-transparent backdrop */
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 1rem;
}

.modal-content {
  background-color: var(--surface-color);
  width: 100%;
  max-width: 950px;
  max-height: 90vh;
  border-radius: 12px;
  box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.modal-header {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--background-color);
}

.modal-header h2 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
}

.modal-close-btn {
  background: none;
  border: none;
  font-size: 1.75rem;
  line-height: 1;
  color: var(--text-secondary);
  transition: var(--transition);
}

.modal-close-btn:hover {
  color: var(--error-color);
}

.modal-body {
  padding: 1.5rem;
  overflow-y: auto;
  flex: 1;
}

/* Product Summary Banner in Modal */
.modal-product-summary {
  background-color: var(--background-color);
  border: 1px solid var(--border-color);
  padding: 1rem 1.25rem;
  border-radius: var(--border-radius);
  margin-bottom: 1.5rem;
}

.summary-desc {
  font-size: 0.925rem;
  color: var(--text-secondary);
  margin-bottom: 0.5rem;
}

.summary-metrics {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.summary-price {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
}

.summary-rating-badge {
  background-color: #fef3c7;
  color: #b45309;
  font-weight: 600;
  font-size: 0.875rem;
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  border: 1px solid #fde68a;
}

/* Main reviews Grid */
.reviews-section-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 1.75rem;
}

@media (max-width: 768px) {
  .reviews-section-grid {
    grid-template-columns: 1fr;
  }
}

/* Reviews List */
.reviews-list-container h3,
.write-review-container h3 {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 1rem;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 0.5rem;
}

.reviews-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-height: 450px;
  overflow-y: auto;
  padding-right: 0.5rem;
}

.review-item {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  padding: 1rem;
  border-radius: var(--border-radius);
}

.review-item-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-bottom: 0.25rem;
}

.review-author {
  font-weight: 600;
  color: var(--text-primary);
}

.review-stars {
  color: #fbbf24;
  font-size: 0.9rem;
  margin-bottom: 0.5rem;
}

.review-comment {
  font-size: 0.9rem;
  color: var(--text-primary);
  line-height: 1.4;
  word-break: break-word;
}

.review-image-attachment {
  margin-top: 0.75rem;
  border-radius: 6px;
  overflow: hidden;
  max-width: 150px;
  border: 1px solid var(--border-color);
}

.attached-review-img {
  width: 100%;
  height: auto;
  display: block;
}

.empty-reviews-state {
  text-align: center;
  padding: 2.5rem 1rem;
  color: var(--text-secondary);
}

.empty-reviews-sub {
  font-size: 0.85rem;
  margin-top: 0.25rem;
}

/* Review Form Styling */
.review-form {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

.star-rating-input {
  display: flex;
  gap: 0.25rem;
}

.star-btn {
  background: none;
  border: none;
  font-size: 1.75rem;
  color: #cbd5e1;
  transition: transform 0.1s ease-in-out, color 0.1s;
}

.star-btn.filled {
  color: #fbbf24;
}

.star-btn:hover {
  transform: scale(1.15);
}

.file-upload-wrapper {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.file-input-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.file-upload-label {
  display: inline-block;
  background-color: var(--background-color);
  border: 1px dashed var(--text-secondary);
  color: var(--text-primary);
  padding: 0.5rem 1rem;
  border-radius: var(--border-radius);
  font-size: 0.875rem;
  text-align: center;
  cursor: pointer;
  transition: var(--transition);
}

.file-upload-label:hover {
  background-color: #f1f5f9;
  border-color: var(--primary-color);
}

.selected-image-preview {
  position: relative;
  width: 80px;
  height: 80px;
  border-radius: var(--border-radius);
  overflow: hidden;
  border: 1px solid var(--border-color);
  margin-top: 0.25rem;
}

.upload-preview-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.clear-image-btn {
  position: absolute;
  top: 2px;
  right: 2px;
  background-color: rgba(15, 23, 42, 0.8);
  color: white;
  border: none;
  border-radius: 50%;
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  cursor: pointer;
}

.auth-prompt-card {
  background-color: #f1f5f9;
  border-radius: var(--border-radius);
  padding: 1.25rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  align-items: center;
}

.submit-review-btn {
  align-self: flex-start;
  min-width: 130px;
}

/* ========================================== */
/*         MODERATION DASHBOARD CSS          */
/* ========================================== */
.moderation-container {
  max-width: var(--max-width);
  margin: 0 auto;
}

.moderation-sub {
  color: var(--text-secondary);
  font-size: 0.925rem;
  margin-bottom: 1.5rem;
}

.moderation-filters {
  display: flex;
  gap: 0.5rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 1rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.filter-tab {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 0.4rem 1rem;
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 500;
  transition: var(--transition);
}

.filter-tab.active {
  background-color: var(--text-primary);
  color: white;
  border-color: var(--text-primary);
}

.empty-moderation {
  text-align: center;
  padding: 4rem 1rem;
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  color: var(--text-secondary);
}

.empty-icon {
  display: inline-block;
  font-size: 2.5rem;
  color: var(--success-color);
  margin-bottom: 1rem;
}

.moderation-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
  gap: 1.5rem;
}

.moderation-card {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1);
  display: flex;
  flex-direction: column;
}

.moderation-card.pending {
  border-left: 4px solid #f59e0b; /* Yellow left border for pending */
}

.moderation-card.approved {
  border-left: 4px solid var(--success-color); /* Green left border */
}

.moderation-card.rejected {
  border-left: 4px solid var(--error-color); /* Red left border */
}

.moderation-card-header {
  padding: 1rem;
