  border-radius: var(--border-radius);
  font-size: 0.875rem;
  text-align: center;
  cursor: pointer;
  transition: var(--transition);
}

.file-upload-label:hover {
  background-color: #f1f5f9;
  border-color: var(--primary-color);
}

.selected-image-preview {
  position: relative;
  width: 80px;
  height: 80px;
  border-radius: var(--border-radius);
  overflow: hidden;
  border: 1px solid var(--border-color);
  margin-top: 0.25rem;
}

.upload-preview-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.clear-image-btn {
  position: absolute;
  top: 2px;
  right: 2px;
  background-color: rgba(15, 23, 42, 0.8);
  color: white;
  border: none;
  border-radius: 50%;
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  cursor: pointer;
}

.auth-prompt-card {
  background-color: #f1f5f9;
  border-radius: var(--border-radius);
  padding: 1.25rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  align-items: center;
}

.submit-review-btn {
  align-self: flex-start;
  min-width: 130px;
}

/* ========================================== */
/*         MODERATION DASHBOARD CSS          */
/* ========================================== */
.moderation-container {
  max-width: var(--max-width);
  margin: 0 auto;
}

.moderation-sub {
  color: var(--text-secondary);
  font-size: 0.925rem;
  margin-bottom: 1.5rem;
}

.moderation-filters {
  display: flex;
  gap: 0.5rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 1rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.filter-tab {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 0.4rem 1rem;
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 500;
  transition: var(--transition);
}

.filter-tab.active {
  background-color: var(--text-primary);
  color: white;
  border-color: var(--text-primary);
}

.empty-moderation {
  text-align: center;
  padding: 4rem 1rem;
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  color: var(--text-secondary);
}

.empty-icon {
  display: inline-block;
  font-size: 2.5rem;
  color: var(--success-color);
  margin-bottom: 1rem;
}

.moderation-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
  gap: 1.5rem;
}

.moderation-card {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1);
  display: flex;
  flex-direction: column;
}

.moderation-card.pending {
  border-left: 4px solid #f59e0b; /* Yellow left border for pending */
}

.moderation-card.approved {
  border-left: 4px solid var(--success-color); /* Green left border */
}

.moderation-card.rejected {
  border-left: 4px solid var(--error-color); /* Red left border */
}

.moderation-card-header {
  padding: 1rem;
  background-color: var(--background-color);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.reviewer-badge {
  font-weight: 600;
  font-size: 0.85rem;
  display: block;
}

.review-date {
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.status-pill {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.2rem 0.5rem;
  border-radius: 9999px;
  letter-spacing: 0.05em;
}

.status-pill.pending {
  background-color: #fef3c7;
  color: #d97706;
}

.status-pill.approved {
  background-color: #dcfce7;
  color: #15803d;
}

.status-pill.rejected {
  background-color: #fee2e2;
  color: #b91c1c;
}

.moderation-card-body {
  padding: 1rem;
  flex: 1;
}

.moderation-product-title {
  font-size: 0.95rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--text-primary);
}

.moderation-comment {
  font-style: italic;
  font-size: 0.875rem;
  color: var(--text-primary);
  margin-top: 0.5rem;
  line-height: 1.4;
  word-break: break-word;
}

.moderation-image-container {
  margin-top: 1rem;
}

.image-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-secondary);
  display: block;
  margin-bottom: 0.25rem;
}

.moderation-thumbnail {
  max-width: 100px;
  max-height: 100px;
  border-radius: 6px;
  border: 1px solid var(--border-color);
  object-fit: cover;
}

.moderation-card-actions {
  padding: 1rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  gap: 0.5rem;
}

.action-btn {
  flex: 1;
  border: none;
  padding: 0.5rem;
  border-radius: var(--border-radius);
  font-weight: 600;
  font-size: 0.875rem;
  transition: var(--transition);
}

.action-btn.approve {
  background-color: var(--success-color);
  color: white;
}

.action-btn.approve:hover {
  background-color: #15803d;
}

.action-btn.reject {
  background-color: var(--error-color);
  color: white;
}

.action-btn.reject:hover {
  background-color: #b91c1c;
}

/* Star styling */
.star {
  color: #cbd5e1;
  margin-right: 2px;
}

.star.filled {
  color: #fbbf24;
}

/* Adjustments for grid layout on Catalog card footer buttons */
.product-card-actions {
  display: flex;
  gap: 0.5rem;
}

.product-card-actions .nav-btn {
  padding: 0.4rem 0.8rem;
  font-size: 0.875rem;
}
